// npm run tokens: writes src/theme/tokens.ts and src/theme/icons.ts from the design system
// (design-system/project/tokens.json and assets/Icons/*.svg). Do not edit the generated files.
import { readFileSync, readdirSync, writeFileSync } from 'node:fs';

const ds = new URL('../../design-system/project/', import.meta.url);
const out = new URL('../src/theme/', import.meta.url);
const tokens = JSON.parse(readFileSync(new URL('tokens.json', ds), 'utf8'));
const camel = (s) => s.replace(/-([a-z0-9])/g, (_, c) => c.toUpperCase());
const px = (v) => Number.parseFloat(v);
const header = '// Generated by scripts/gen-tokens.mjs from design-system/project. Do not edit.\n';

const raw = Object.fromEntries(tokens.color.tokens.map((t) => [t.name, t.value]));
const color = Object.fromEntries(
  Object.entries(raw).map(([k, v]) => [camel(k), v.replace(/^\{(.+)\}$/, (_, ref) => raw[ref])]),
);
const type = Object.fromEntries(
  tokens.type.groups.flatMap((g) => g.styles).map((s) => [
    camel(s.name),
    {
      fontSize: px(s.fontSize),
      lineHeight: px(s.lineHeight),
      fontWeight: s.fontWeight,
      ...(s.letterSpacing ? { letterSpacing: +(px(s.letterSpacing) * px(s.fontSize)).toFixed(2) } : {}),
    },
  ]),
);
const scale = (group, prefix) =>
  Object.fromEntries(tokens[group].tokens.map((t) => [camel(t.name.replace(prefix, '')), t.value]));
const space = Object.fromEntries(Object.entries(scale('spacing', 'space-')).map(([k, v]) => [k, px(v)]));
const radius = Object.fromEntries(Object.entries(scale('radius', 'radius-')).map(([k, v]) => [k, px(v)]));
const shadow = scale('shadow', 'shadow-');

writeFileSync(
  new URL('tokens.ts', out),
  header +
    `export const color = ${JSON.stringify(color, null, 2)} as const;\n\n` +
    `export const type = ${JSON.stringify(type, null, 2)} as const;\n\n` +
    `export const space = ${JSON.stringify(space, null, 2)} as const;\n\n` +
    `export const radius = ${JSON.stringify(radius, null, 2)} as const;\n\n` +
    `export const shadow = ${JSON.stringify(shadow, null, 2)} as const;\n\n` +
    `export const fallbackFonts = ${JSON.stringify(tokens.type.families.sans.split(',').slice(1).join(',').trim())};\n`,
);

// Each icon becomes a list of SVG elements with their attributes (path, circle, rect).
const icons = {};
const iconDir = new URL('assets/Icons/', ds);
for (const file of readdirSync(iconDir).filter((f) => f.endsWith('.svg')).sort()) {
  const svg = readFileSync(new URL(file, iconDir), 'utf8');
  icons[camel(file.replace('.svg', ''))] = [...svg.matchAll(/<(path|circle|rect)\s([^>]*?)\/>/g)].map(([, tag, attrs]) => ({
    tag,
    ...Object.fromEntries([...attrs.matchAll(/([a-z]+)="([^"]*)"/g)].map(([, k, v]) => [k, v])),
  }));
}
writeFileSync(
  new URL('icons.ts', out),
  header +
    '// Lucide icons (ISC licence) chosen for 海豚云; see design-system/project/assets/Icons/README.md.\n' +
    `export const icons = ${JSON.stringify(icons, null, 2)} as const;\n\nexport type IconName = keyof typeof icons;\n`,
);
console.log(`tokens: ${Object.keys(color).length} colours, ${Object.keys(type).length} type styles; icons: ${Object.keys(icons).length}`);
